from research_os.core.types import EvidenceLevel,GateStatus
from research_os.knowledge import KnowledgeLab,ReviewStatus,Zettel,ZettelType,SourceLocator,write_zettel,zettel_to_training_record
def test_verified_zettel_requires_source_locator():
    run=KnowledgeLab().run({"title":"Hall-Petch relation","summary":"Grain size is related to yield strength within the model applicability range.","domain":"physical_metallurgy","zettel_type":"principle","evidence_level":"E4_CURATED_EXPERIMENTAL","review_status":"VERIFIED"}); assert not run.passed; assert run.first_loss.rule_id=="KNOW-SRC-001"; assert run.first_loss.status==GateStatus.INSUFFICIENT_EVIDENCE
def test_reviewed_zettel_keeps_evidence_level_separate_from_review_status():
    run=KnowledgeLab().run({"title":"A heuristic design note","summary":"A local heuristic used to rank candidates.","domain":"design","zettel_type":"method","evidence_level":"E0_HEURISTIC","review_status":"VERIFIED","sources":[{"source_id":"internal-method-v1"}]}); assert run.passed; assert run.evidence[-1].level==EvidenceLevel.E0_HEURISTIC; assert run.evidence[-1].payload["zettel"]["review_status"]==ReviewStatus.VERIFIED.value
def test_zettel_markdown_and_training_record_are_attributable(tmp_path):
    z=Zettel(title="Nickel superalloy note",summary="An atomic summary written for the local knowledge base.",zettel_type=ZettelType.MATERIAL,domain="metallurgy",evidence_level=EvidenceLevel.E4_CURATED_EXPERIMENTAL,review_status=ReviewStatus.VERIFIED,tags=("nickel","superalloy"),links=("Gamma prime",),sources=(SourceLocator(source_id="BOOK-001",chapter="3",page="42"),)); path=write_zettel(z,tmp_path); text=path.read_text(); assert z.zettel_id in text; assert "[[Gamma prime]]" in text; record=zettel_to_training_record(z); assert record["id"]==z.zettel_id; assert record["sources"][0]["source_id"]=="BOOK-001"; assert record["digest"]==z.digest
